class Counter {
    static int created = 0;      // 1 ban duy nhat cho ca class
    int value = 10;              // field initializer: chay khi new
    int doubled;

    {
        // instance initializer block: chay sau field initializer,
        // truoc than constructor
        doubled = value * 2;
    }

    Counter() {
        created++;
        System.out.println(value + " / " + doubled); // 10 / 20
    }

    public static void main(String[] args) {
        Counter a = new Counter();
        Counter b = a;           // KHONG tao object moi: copy reference
        b.value = 99;
        System.out.println(a.value);      // 99 - cung mot object
        System.out.println(Counter.created); // 1 - chi new mot lan
    }
}

class Book {
    private final String title;
    private final String author;
    private final int totalPages;

    public Book(String title, String author, int totalPages) {
        this.title = title;
        this.author = author;
        this.totalPages = totalPages;
    }

    // chained constructor: tac gia mac dinh 'Unknown'
    public Book(String title, int totalPages) {
        this(title, "Unknown", totalPages);
    }

    public String getTitle() {
        return title;
    }
}

