public class BankAccount {
    private final double balance;

    public BankAccount(double initialBalance) {
        if (initialBalance < 0) {
            throw new IllegalArgumentException("balance khong duoc am");
        }
        this.balance = initialBalance;
    }

    public double getBalance() {
        return balance;
    }
}
